import { useEffect, useMemo, useState } from 'react'
import { Link } from 'react-router-dom'
import { BarChart3, CalendarRange, Check, Download, Timer } from 'lucide-react'
import { errorMessage, get, post } from '../lib/api'
import { Badge, Button, Empty, Field, LoadFailed, Loading, Modal, StatusBadge, useDownload, useToast } from '../components/ui'

type Row = Record<string, string | number | boolean>
type Report = {
  from: string; to: string
  totals: { created: number; submitted: number; completed: number; rejected: number; in_progress: number }
  cycle_time: { measured: number; average_days: number; median_days: number; p90_days: number }
  by_status: Row[]; by_department: Row[]; by_result: Row[]; recurring_findings: Row[]; repeated_findings?: Row[]; follow_ups: Row[]; follow_ups_total: number; aging: Row[]
}
const resultLabel: Record<string, string> = { COMPLIANT: '적합', CONDITIONAL: '조건부 적합', INSUFFICIENT: '미흡', NON_COMPLIANT: '부적합', NA_ACCEPTED: 'N/A 인정', RECHECK: '재확인' }

// Defaulting to the current month is what a monthly report actually needs.
function monthStart() { const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), 1).toISOString().slice(0, 10) }
function today() { return new Date().toISOString().slice(0, 10) }

export default function Reports() {
  const toast = useToast()
  const save = useDownload()
  const [filter, setFilter] = useState({ from: monthStart(), to: today(), department: '' })
  const [includeDone, setIncludeDone] = useState(false)
  const [data, setData] = useState<Report>()
  const params = useMemo(() => { const qs = new URLSearchParams(); Object.entries(filter).forEach(([k, v]) => { if (v) qs.set(k, v) }); if (includeDone) qs.set('include_done', '1'); return qs }, [filter, includeDone])
  const [failed, setFailed] = useState<unknown>()
  const reload = () => { setFailed(undefined); return get<Report>(`/api/v1/reports/reviews?${params}`).then(setData).catch(setFailed) }
  useEffect(() => { setData(undefined); const timer = window.setTimeout(reload, 200); return () => clearTimeout(timer) }, [params])
  const set = (key: keyof typeof filter, value: string) => setFilter(v => ({ ...v, [key]: value }))
  // The list filters the same period the report does -- both read created_at --
  // so a row can open exactly the reviews it counted.
  const periodQuery = `&from=${filter.from}&to=${filter.to}`
  const preset = (months: number) => { const d = new Date(); const start = new Date(d.getFullYear(), d.getMonth() - months + 1, 1); setFilter(v => ({ ...v, from: start.toISOString().slice(0, 10), to: today() })) }

  return <div className="page">
    <div className="page-header"><div><h1 className="page-title">심의 리포트</h1><p className="page-description">기간별 심의 처리 현황과 반복 지적 사항을 집계합니다. 보고용 Excel로 내려받을 수 있습니다.</p></div>
      <Button variant="primary" onClick={() => save(`/api/v1/reports/reviews?${new URLSearchParams({ ...Object.fromEntries(params), format: 'xlsx' })}`)}><Download size={14} /> Excel 리포트</Button></div>

    <div className="card"><div className="card-body"><div className="form-grid compact">
      <Field label="시작일"><input type="date" className="input" max={filter.to} value={filter.from} onChange={e => set('from', e.target.value)} /></Field>
      <Field label="종료일"><input type="date" className="input" min={filter.from} value={filter.to} onChange={e => set('to', e.target.value)} /></Field>
      <Field label="부서" help="비우면 전체"><input className="input" value={filter.department} onChange={e => set('department', e.target.value)} /></Field>
      <div className="field"><label>기간 선택</label><div className="header-actions"><Button small onClick={() => preset(1)}>이번 달</Button><Button small onClick={() => preset(3)}>최근 3개월</Button><Button small onClick={() => preset(12)}>최근 1년</Button></div></div>
    </div></div></div>

    {failed ? <LoadFailed error={failed} onRetry={reload} /> : !data ? <Loading /> : <>
      <div className="grid stats">
        <div className="card stat-card"><div className="stat-icon"><CalendarRange /></div><div><span className="stat-value">{data.totals.created}</span><div className="stat-label">신규 심의</div></div></div>
        <div className="card stat-card"><div className="stat-icon green"><BarChart3 /></div><div><span className="stat-value">{data.totals.completed}</span><div className="stat-label">완료</div></div></div>
        <div className="card stat-card"><div className="stat-icon amber"><BarChart3 /></div><div><span className="stat-value">{data.totals.in_progress}</span><div className="stat-label">진행 중</div></div></div>
        <div className="card stat-card"><div className="stat-icon red"><BarChart3 /></div><div><span className="stat-value">{data.totals.rejected}</span><div className="stat-label">반려</div></div></div>
      </div>

      <section className="card"><div className="card-header"><h2><Timer size={17} /> 처리 기간 (제출 → 승인)</h2><Badge>{data.cycle_time.measured}건 기준</Badge></div>
        <div className="card-body">{data.cycle_time.measured ? <div className="grid three">
          <div><span className="subtle">평균</span><div className="stat-value">{data.cycle_time.average_days}일</div></div>
          <div><span className="subtle">중앙값</span><div className="stat-value">{data.cycle_time.median_days}일</div></div>
          <div><span className="subtle">90분위</span><div className="stat-value">{data.cycle_time.p90_days}일</div></div>
        </div> : <Empty title="이 기간에 완료된 심의가 없습니다." description="처리 기간은 제출부터 최종 승인까지를 측정합니다." />}</div></section>

      <div className="grid two">
        <ReportTable title="상태별" rows={data.by_status} columns={[['status', '상태'], ['count', '건수']]} render={{ status: v => <Link className="table-link" to={`/reviews?status=${encodeURIComponent(String(v))}${periodQuery}`}><StatusBadge status={String(v)} /></Link> }} />
        <ReportTable title="검토 결과 분포" rows={data.by_result} columns={[['result', '판정'], ['count', '항목 수']]} render={{ result: v => <>{resultLabel[String(v)] || String(v)}</> }} />
      </div>
      <ReportTable title="부서별 현황" rows={data.by_department} columns={[['department', '부서'], ['created', '신규'], ['completed', '완료'], ['average_days', '평균 처리일']]} render={{ department: v => <Link className="table-link" to={`/reviews?department=${encodeURIComponent(String(v))}${periodQuery}`}>{String(v)}</Link> }} />
      <ReportTable title="같은 서비스에서 반복된 지적" rows={data.repeated_findings || []} columns={[['service_name', '서비스'], ['department', '부서'], ['item_code', '항목코드'], ['title', '보안요건'], ['times', '지적 횟수'], ['last_decided_on', '마지막 판정일']]} empty="같은 항목이 두 번 이상 지적된 서비스가 없습니다." />
      <ReportTable title="반복 미흡·부적합 항목" rows={data.recurring_findings} columns={[['item_code', '항목코드'], ['title', '보안요건'], ['category', '분류'], ['count', '발생 건수']]} empty="이 기간에 미흡·부적합 판정이 없습니다." />
      <FollowUpTable rows={data.follow_ups} total={data.follow_ups_total} includeDone={includeDone} onToggleScope={() => setIncludeDone(v => !v)} onChanged={reload} />
      <ReportTable title="진행 중 심의 경과" rows={data.aging} columns={[['bucket', '최근 변경 이후'], ['count', '건수']]} empty="진행 중인 심의가 없습니다." />
    </>}
  </div>
}

function ReportTable({ title, rows, columns, render, empty }: { title: string; rows: Row[]; columns: [string, string][]; render?: Record<string, (v: unknown) => React.ReactNode>; empty?: string }) {
  return <section className="card"><div className="card-header"><h2>{title}</h2><Badge>{rows.length}</Badge></div>
    {rows.length ? <div className="table-wrap"><table><caption className="sr-only">{title}</caption>
      <thead><tr>{columns.map(([key, label]) => <th key={key} scope="col">{label}</th>)}</tr></thead>
      <tbody>{rows.map((row, i) => <tr key={i}>{columns.map(([key]) => <td key={key}>{render?.[key] ? render[key](row[key]) : String(row[key] ?? '-')}</td>)}</tr>)}</tbody>
    </table></div> : <Empty title={empty || '집계할 데이터가 없습니다.'} />}
  </section>
}

// The register is the work left over from reviewing. Closing an entry here
// rather than inside the review it came from is the point: by the time an
// action falls due, nobody is looking at that review any more.
function FollowUpTable({ rows, total, includeDone, onToggleScope, onChanged }: { rows: Row[]; total: number; includeDone: boolean; onToggleScope: () => void; onChanged: () => Promise<void> | void }) {
  const toast = useToast()
  const [busy, setBusy] = useState('')
  const [closing, setClosing] = useState<Row>()
  const [note, setNote] = useState('')
  const mark = async (row: Row, done: boolean, result = '') => {
    setBusy(String(row.id))
    try {
      await post(`/api/v1/review-results/${row.id}/follow-up`, { action: done ? 'confirm' : 'reopen', note: result })
      toast.push(done ? '이행 확인 처리했습니다.' : '이행 완료를 해제했습니다.')
      setClosing(undefined); setNote('')
      await onChanged()
    } catch (e) { toast.push(errorMessage(e), 'error') } finally { setBusy('') }
  }
  return <section className="card">
    <div className="card-header"><h2>미조치 항목</h2><Badge>{total > rows.length ? `${rows.length} / ${total}` : rows.length}</Badge>
      <div className="header-actions"><button type="button" className={`chip ${includeDone ? 'on' : ''}`} aria-pressed={includeDone} onClick={onToggleScope} title="이행이 끝난 조치와, 심의가 취소되어 더 이상 쫓지 않는 조치까지 함께 봅니다.">이행 완료 포함</button></div></div>
    {total > rows.length && <div className="card-body"><p className="subtle">전체 {total.toLocaleString('ko-KR')}건 중 {rows.length.toLocaleString('ko-KR')}건만 표시합니다. 전체 목록은 Excel 내보내기로 확인하세요.</p></div>}
    {rows.length ? <div className="table-wrap"><table><caption className="sr-only">미조치 항목</caption>
      <thead><tr><th scope="col">심의</th><th scope="col">항목</th><th scope="col">판정</th><th scope="col">조치 사항</th><th scope="col">상태</th><th scope="col"><span className="sr-only">작업</span></th></tr></thead>
      <tbody>{rows.map(row => <tr key={String(row.id)}>
        <td>{row.review_id ? <Link className="table-link" to={`/reviews/${row.review_id}${row.item_id ? `?item=${row.item_id}` : ''}`}>{String(row.review_number)}</Link> : String(row.review_number)}<div className="subtle">{String(row.service_name)}{row.department ? ` · ${row.department}` : ''}</div>{row.review_status === 'CANCELLED' && <Badge>심의 취소됨</Badge>}</td>
        <td>{String(row.item_code)}<div className="subtle">{String(row.title)}</div></td>
        <td>{resultLabel[String(row.result)] || String(row.result)}</td>
        <td>{String(row.follow_up)}<div className="subtle">{String(row.decided_on)} 판정{row.due_on ? ` · 기한 ${row.due_on}` : ''}</div></td>
        <td>{row.done_on
          ? <><Badge tone="green">이행 확인</Badge><div className="subtle">{String(row.done_on)} · {String(row.done_by)}</div>{row.follow_up_note ? <div className="subtle">{String(row.follow_up_note)}</div> : null}</>
          : row.reported_on
            ? <><Badge tone="blue">조치 보고됨</Badge><div className="subtle">{String(row.reported_on)} · {String(row.reported_by)}</div>{row.follow_up_note ? <div className="subtle">{String(row.follow_up_note)}</div> : null}</>
            : row.overdue ? <><Badge tone="red">기한 초과</Badge><div className="subtle">{String(row.due_on)}까지</div></> : <><Badge tone="amber">미조치</Badge>{!row.due_on && <div className="subtle">기한 없음 · 알림이 가지 않습니다</div>}</>}</td>
        <td>{row.can_close === false
          ? <span className="subtle" title="이 심의의 담당 보안 담당자만 이행 확인과 해제를 할 수 있습니다.">담당 검토자만 처리</span>
          : row.done_on
            ? <Button small disabled={busy === String(row.id)} onClick={() => mark(row, false)}>해제</Button>
            : <Button small variant="primary" disabled={busy === String(row.id)} onClick={() => { setClosing(row); setNote('') }}><Check size={13} /> 이행 확인</Button>}</td>
      </tr>)}</tbody></table></div>
      : <Empty title={includeDone ? '조치 사항이 기록된 항목이 없습니다.' : '미조치 항목이 없습니다.'} description="검토자가 판정과 함께 남긴 조치 사항이 여기 모입니다." />}
    {closing && <Modal title={closing.reported_on ? '보고된 조치 확인' : '이행 확인 처리'} onClose={() => setClosing(undefined)}
      footer={<><Button onClick={() => setClosing(undefined)}>취소</Button><Button variant="primary" disabled={busy !== ''} onClick={() => mark(closing, true, note)}>이행 확인</Button></>}>
      <div className="guide-block">{String(closing.review_number)} · {String(closing.item_code)}<br />{String(closing.follow_up)}</div>
      {closing.reported_on ? <div className="guide-block">{String(closing.reported_by)}이(가) {String(closing.reported_on)}에 보고했습니다{closing.follow_up_note ? `: ${closing.follow_up_note}` : ''}</div> : null}
      <Field label="이행 결과" help="비우면 보고된 내용을 그대로 유지합니다."><textarea className="textarea" value={note} onChange={e => setNote(e.target.value)} /></Field>
    </Modal>}
  </section>
}
import { useEffect, useMemo, useRef, useState } from 'react'
import { Link, useSearchParams } from 'react-router-dom'
import { Download, RotateCcw, Search, ShieldCheck } from 'lucide-react'
import { errorMessage, get } from '../lib/api'
import { Badge, Button, Empty, Field, LoadFailed, Loading, Modal, formatDate, useDownload, useToast } from '../components/ui'

const today = () => new Date().toISOString().slice(0, 10)

export default function AuditPage() {
  const toast = useToast()
  const save = useDownload()
  const [items, setItems] = useState<Record<string, unknown>[]>()
  const [events, setEvents] = useState<{ code: string; label: string }[]>([])
  // Another screen can hand the log a target to look at, so "what happened to
  // this Control" is one link away from the Control itself.
  const [search, setSearch] = useSearchParams()
  const [filter, setFilter] = useState({ event: '', user: '', target: search.get('target') || '', target_type: search.get('target_type') || '', event_id: search.get('event_id') || '', result: '', from: '', to: '', limit: '200' })
  const [detail, setDetail] = useState<Record<string, unknown>>()
  const params = useMemo(() => { const qs = new URLSearchParams(); Object.entries(filter).forEach(([k, v]) => { if (v) qs.set(k, v) }); return qs }, [filter])
  // The log is the record an investigation works through, and the screen used
  // to stop at the newest page without saying so. Older events are now one
  // button away instead of a guess at date filters.
  const [offset, setOffset] = useState(0)
  const [hasMore, setHasMore] = useState(false)
  const key = params.toString()
  const lastKey = useRef(key)
  const [failed, setFailed] = useState<unknown>()
  useEffect(() => {
    if (lastKey.current !== key) { lastKey.current = key; if (offset !== 0) { setOffset(0); return } }
    if (!offset) setItems(undefined)
    const qs = new URLSearchParams(params); qs.set('offset', String(offset))
    const timer = window.setTimeout(() => {
      get<{ items: Record<string, unknown>[]; events: { code: string; label: string }[]; has_more: boolean }>(`/api/v1/admin/audit?${qs}`).then(page => {
        setItems(prev => (offset && prev ? [...prev, ...page.items] : page.items))
        setHasMore(Boolean(page.has_more))
        if (page.events?.length) setEvents(page.events)
        setFailed(undefined)
      }).catch(setFailed)
    }, 200)
    return () => clearTimeout(timer)
  }, [key, offset])
  const [verifying, setVerifying] = useState(false)
  // The routine check only proves what has been appended since the last run;
  // a full pass re-hashes the whole chain and is offered separately.
  const verify = async (full = false) => {
    setVerifying(true)
    try {
      const r = await get<{ valid: boolean; checked: number; total?: number; from_sequence: number; reason?: string }>(`/api/v1/admin/audit/verify${full ? '?full=1' : ''}`)
      if (!r.valid) { toast.push(`체인 불일치가 발견되었습니다 (${r.reason || '무결성 오류'}). 시스템 관리자에게 알림이 발송되었습니다.`, 'error'); return }
      toast.push(full
        ? `전체 ${r.checked}개 감사 이벤트의 해시 체인이 유효합니다.`
        : r.checked === 0 ? '이전 검증 이후 추가된 이벤트가 없습니다. 체인은 유효합니다.' : `신규 ${r.checked}개 이벤트를 검증했습니다. 누적 ${r.total ?? r.checked}개까지 체인이 유효합니다.`)
    } catch (e) { toast.push(errorMessage(e), 'error') } finally { setVerifying(false) }
  }
  const set = (key: keyof typeof filter, value: string) => setFilter(v => ({ ...v, [key]: value }))
  // The address bar carries the target so the filtered view can be shared.
  useEffect(() => { const next = new URLSearchParams(search); filter.target ? next.set('target', filter.target) : next.delete('target'); filter.target_type ? next.set('target_type', filter.target_type) : next.delete('target_type'); filter.event_id ? next.set('event_id', filter.event_id) : next.delete('event_id'); if (next.toString() !== search.toString()) setSearch(next, { replace: true }) }, [filter.target, filter.target_type])
  const active = Boolean(filter.event || filter.user || filter.target || filter.target_type || filter.event_id || filter.result || filter.from || filter.to)
  return <div className="page">
    <div className="page-header"><div><h1 className="page-title">감사로그</h1><p className="page-description">이전 이벤트 해시를 연결한 위변조 탐지 체인입니다. 애플리케이션에서 수정·삭제 API를 제공하지 않습니다.</p></div><div className="header-actions"><Button onClick={() => save(`/api/v1/admin/audit?${new URLSearchParams({ ...Object.fromEntries(params), format: 'csv' })}`)}><Download size={14} /> CSV 내보내기</Button><Button disabled={verifying} onClick={() => verify(false)}><ShieldCheck size={14} /> 체인 검증</Button><Button disabled={verifying} onClick={() => verify(true)}>전체 재검증</Button></div></div>
    <div className="card"><div className="card-body"><div className="form-grid">
      <Field label="이벤트 유형" help="앞부분만 입력해도 됩니다. 예: LOGIN"><div className="search-box"><Search /><input className="input" list="audit-events" placeholder="목록에서 고르거나 직접 입력" value={filter.event} onChange={e => set('event', e.target.value)} /><datalist id="audit-events">{events.map(e => <option key={e.code} value={e.code}>{e.label}</option>)}</datalist></div></Field>
      <Field label="사용자 / 접속 IP"><input className="input" placeholder="이름 또는 IP 일부" value={filter.user} onChange={e => set('user', e.target.value)} /></Field>
      <Field label="대상 ID" help="표의 대상 값을 누르면 그 대상의 이력만 남습니다."><input className="input" placeholder="심의·Control·템플릿 ID" value={filter.target} onChange={e => set('target', e.target.value)} /></Field>
      <Field label="이벤트 ID" help="무결성 실패 알림이 가리키는 그 이벤트만 봅니다."><input className="input" placeholder="감사 이벤트 ID" value={filter.event_id} onChange={e => set('event_id', e.target.value)} /></Field>
      <Field label="결과" help="거부된 시도만 모아 봅니다."><select className="select" value={filter.result} onChange={e => set('result', e.target.value)}><option value="">전체</option><option value="SUCCESS">성공</option><option value="FAILURE">실패·거부</option></select></Field>
      <Field label="시작일"><input type="date" className="input" max={filter.to || today()} value={filter.from} onChange={e => set('from', e.target.value)} /></Field>
      <Field label="종료일"><input type="date" className="input" min={filter.from} max={today()} value={filter.to} onChange={e => set('to', e.target.value)} /></Field>
      <Field label="표시 건수"><select className="select" value={filter.limit} onChange={e => set('limit', e.target.value)}><option value="50">50</option><option value="200">200</option></select></Field>
      <div className="field"><label>&nbsp;</label><Button disabled={!active} onClick={() => setFilter({ event: '', user: '', target: '', target_type: '', event_id: '', result: '', from: '', to: '', limit: filter.limit })}><RotateCcw size={13} /> 필터 초기화</Button></div>
    </div></div>
      {failed ? <LoadFailed error={failed} /> : !items ? <Loading /> : items.length ? <div className="table-wrap"><table><thead><tr><th>시각</th><th>이벤트</th><th>사용자 / IP</th><th>대상</th><th>결과</th><th>해시</th></tr></thead><tbody>{items.map(x => <tr key={String(x.event_id)}><td>{formatDate(x.timestamp, true)}</td><td><button className="link-button" onClick={() => setDetail(x)}><Badge tone="blue">{String(x.event_label || x.event_type)}</Badge></button><div className="subtle">{String(x.event_type)}</div></td><td>{String(x.user_name || '-')}<div className="subtle">{String(x.source_ip || '')}</div></td><td>{x.target_id ? <button className="link-button" title="이 대상의 이력만 보기" onClick={() => setFilter(v => ({ ...v, target: String(x.target_id), target_type: String(x.target_type || '') }))}>{String(x.target_type)}<div className="subtle">{String(x.target_id)}</div></button> : <>{String(x.target_type)}</>}</td><td><Badge tone={x.result === 'SUCCESS' ? 'green' : 'red'}>{String(x.result)}</Badge></td><td><code title={String(x.event_hash)}>{String(x.event_hash).slice(0, 12)}…</code></td></tr>)}</tbody></table></div> : <Empty title="조건에 맞는 감사 이벤트가 없습니다." description="필터를 넓히거나 기간을 조정하세요." />}
      {items && hasMore && <div className="card-body"><Button small onClick={() => setOffset(items.length)}>더 보기 (현재 {items.length.toLocaleString('ko-KR')}건)</Button> <span className="subtle">더 오래된 이벤트가 남아 있습니다.</span></div>}
    </div>
    {detail && <AuditDetail event={detail} onClose={() => setDetail(undefined)} />}
  </div>
}

function AuditDetail({ event, onClose }: { event: Record<string, unknown>; onClose: () => void }) {
  const rows: [string, string][] = [['이벤트', `${event.event_label || ''} (${event.event_type})`.trim()], ['시각', formatDate(event.timestamp, true)], ['사용자', String(event.user_name || '-')], ['접속 IP', String(event.source_ip || '-')], ['대상', `${event.target_type} ${event.target_id || ''}`.trim()], ['결과', String(event.result)], ['요청 ID', String(event.request_id || '-')], ['이전 해시', String(event.previous_hash || '-')], ['이벤트 해시', String(event.event_hash || '-')]]
  // Built by hand, this dialog missed everything the shared one does for a
  // keyboard user, so it uses the shared one.
  // The event names a review; being able to open it is the other half of the
  // link that leads from a review's history into this log.
  const review = event.target_type === 'REVIEW_REQUEST' && event.target_id ? String(event.target_id) : ''
  return <Modal title="감사 이벤트 상세" onClose={onClose} footer={<>{review && <Link className="button" to={`/reviews/${review}`} onClick={onClose}>심의 열기</Link>}<Button onClick={onClose}>닫기</Button></>}>
    <div className="table-wrap"><table><tbody>{rows.map(([label, value]) => <tr key={label}><th>{label}</th><td style={{ wordBreak: 'break-all' }}>{value}</td></tr>)}</tbody></table></div>
    {Boolean(event.before_value) && <><h4>변경 전</h4><div className="guide-block"><code>{JSON.stringify(event.before_value, null, 2)}</code></div></>}
    {Boolean(event.after_value) && <><h4>변경 후</h4><div className="guide-block"><code>{JSON.stringify(event.after_value, null, 2)}</code></div></>}
  </Modal>
}
