name: security-ci

on:
  push:
    branches: [main]
  pull_request:
  # GitHub occasionally does not create a run for a push. Without a manual
  # trigger the only way to get one is to push again, which puts an empty
  # commit in the history of a release just to make the checks appear.
  workflow_dispatch:

permissions:
  contents: read
  security-events: write

jobs:
  test-build-scan:
    runs-on: ubuntu-latest
    services:
      postgres:
        image: postgres:16-alpine
        env:
          POSTGRES_PASSWORD: seccheck_ci
          POSTGRES_DB: seccheck
        ports:
          - 5432:5432
        options: >-
          --health-cmd "pg_isready -U postgres -d seccheck"
          --health-interval 5s
          --health-timeout 5s
          --health-retries 20
    steps:
      - uses: actions/checkout@3d3c42e5aac5ba805825da76410c181273ba90b1 # v7.0.1
      - uses: actions/setup-go@b7ad1dad31e06c5925ef5d2fc7ad053ef454303e # v7.0.0
        with:
          go-version-file: go.mod
          cache: true
      - uses: actions/setup-node@820762786026740c76f36085b0efc47a31fe5020 # v7.0.0
        with:
          node-version: 22
          cache: npm
          cache-dependency-path: web/package-lock.json
      - name: Unit and database integration tests
        env:
          TEST_POSTGRES_DSN: postgres://postgres:seccheck_ci@127.0.0.1:5432/seccheck?sslmode=disable
        run: |
          go test -race -coverprofile=coverage.out ./...
          go vet ./...
      - name: Go vulnerability scan
        run: |
          go install golang.org/x/vuln/cmd/govulncheck@latest
          govulncheck ./...
      - name: Frontend build and dependency gate
        run: |
          npm ci --prefix web --no-audit --no-fund
          npm --prefix web test --silent
          npm --prefix web run build
          npm audit --prefix web --audit-level=high
      # The published action now asks for a licence key from a service this
      # pipeline cannot depend on -- it failed the build with "missing gitleaks
      # license" and, on another run, crashed the runner's log encoder while
      # printing that message. The scanner itself is the same binary, so it is
      # run straight from the official image, pinned by digest like everything
      # else here.
      # --no-git scans the tree as it stands rather than one commit's diff:
      # the checkout is shallow, so a push of several commits would otherwise
      # have only its last one looked at.
      - name: Secret scan
        run: |
          docker run --rm -v "$PWD:/repo" \
            ghcr.io/gitleaks/gitleaks@sha256:c00b6bd0aeb3071cbcb79009cb16a60dd9e0a7c60e2be9ab65d25e6bc8abbb7f \
            detect --source=/repo --no-git --redact --no-banner --exit-code 1
      - name: Build release-shaped image
        run: docker build --build-arg VERSION=1.0.146 -t seccheck:v1.0.146 .
      - name: Container vulnerability gate
        uses: aquasecurity/trivy-action@ed142fd0673e97e23eac54620cfb913e5ce36c25 # v0.36.0
        with:
          image-ref: seccheck:v1.0.146
          format: sarif
          output: trivy.sarif
          severity: CRITICAL,HIGH
          ignore-unfixed: true
          exit-code: 1
      - uses: github/codeql-action/upload-sarif@5595ccaf912efad79be6eef63a5619ff05969be3 # v4.37.6
        if: ${{ always() && hashFiles('trivy.sarif') != '' }}
        with:
          sarif_file: trivy.sarif
      - name: Generate CycloneDX SBOM
        uses: anchore/sbom-action@e22c389904149dbc22b58101806040fa8d37a610 # v0.24.0
        with:
          image: seccheck:v1.0.146
          format: cyclonedx-json
          output-file: sbom.cdx.json
          upload-artifact: false
          upload-release-assets: false
      - name: Scan SBOM for fixable vulnerabilities
        uses: anchore/scan-action@e1165082ffb1fe366ebaf02d8526e7c4989ea9d2 # v7.4.0
        with:
          sbom: sbom.cdx.json
          severity-cutoff: high
          only-fixed: true
          fail-build: true
      - name: Container integration smoke test
        run: |
          docker run -d --name seccheck-ci --network host \
            -e POSTGRES_DSN='postgres://postgres:seccheck_ci@127.0.0.1:5432/seccheck?sslmode=disable' \
            -e BOOTSTRAP_ADMIN=admin \
            -e BOOTSTRAP_ADMIN_PASSWORD='CiPassword123!' \
            -e ENCRYPTION_KEY="$(openssl rand -base64 32)" \
            seccheck:v1.0.146
          for i in $(seq 1 30); do curl -fsS http://127.0.0.1:8080/ready && break; sleep 2; done
          curl -fsS http://127.0.0.1:8080/health | grep '"status":"ok"'
          curl -fsS -H 'Content-Type: application/json' \
            -d '{"username":"admin","password":"CiPassword123!"}' \
            http://127.0.0.1:8080/api/v1/auth/login | grep 'SYSTEM_ADMIN'
      - name: Account lockout smoke test
        run: |
          for i in $(seq 1 5); do
            curl -s -o /dev/null -H 'Content-Type: application/json' \
              -d '{"username":"admin","password":"WrongPassword123!"}' \
              http://127.0.0.1:8080/api/v1/auth/login
          done
          curl -s -H 'Content-Type: application/json' \
            -d '{"username":"admin","password":"CiPassword123!"}' \
            http://127.0.0.1:8080/api/v1/auth/login | grep 'ACCOUNT_LOCKED'
      - name: DAST baseline
        uses: zaproxy/action-baseline@de8ad967d3548d44ef623df22cf95c3b0baf8b25 # v0.15.0
        with:
          target: http://127.0.0.1:8080
          rules_file_name: .zap/rules.tsv
          fail_action: true
          allow_issue_writing: false
#!/usr/bin/env bash
# What CI will say, said here first.
#
# The secret scan has now failed twice on a push that looked harmless -- test
# password literals once, a list of passwords the service must refuse the
# other time -- and each time the answer came twenty minutes after the commit
# was already public. Everything here is a check the pipeline runs; the point
# is to run the cheap ones before pushing rather than after.
#
# Usage:  scripts/precheck.sh            (skips what it cannot run)
#         TEST_POSTGRES_DSN=... scripts/precheck.sh
set -uo pipefail
cd "$(dirname "$0")/.."

failed=0
step() { printf '\n=== %s\n' "$1"; }
fail() { printf '!!! %s\n' "$1"; failed=1; }

step "gofmt"
unformatted="$(gofmt -l . | grep -v '^web/' || true)"
if [ -n "$unformatted" ]; then
  fail "gofmt은 다음 파일을 다시 쓰고 싶어 합니다:"; printf '%s\n' "$unformatted"
fi

step "go vet"
go vet ./... || fail "go vet 실패"

step "go test"
if [ -n "${TEST_POSTGRES_DSN:-}" ]; then
  go test ./... || fail "테스트 실패"
else
  printf '건너뜀: TEST_POSTGRES_DSN이 없어 데이터베이스 테스트가 모두 skip됩니다.\n'
  printf '        CI는 PostgreSQL과 함께 돌리므로, 여기서 통과해도 CI가 통과한다는 뜻은 아닙니다.\n'
  go test ./... || fail "테스트 실패"
fi

step "프런트엔드"
if [ -d web/node_modules ]; then
  # The vitest suite reads the request bodies the screens write out and holds
  # them against internal/web/payloads.go -- a Go change that renames a field
  # is caught here, not by the person whose dialog starts answering 400.
  (cd web && npx tsc --noEmit && npm test --silent && npm run build >/dev/null) || fail "프런트엔드 타입체크·테스트 또는 빌드 실패"
else
  printf '건너뜀: web/node_modules가 없습니다 (cd web && npm ci).\n'
fi

step "가이드 그림"
# The guides are only as honest as their pictures. A reference to a capture
# that is not there makes the PDF build fail, but only once someone runs it;
# a capture nothing references is a screen the guide silently stopped
# showing after a rename. Both directions are checked, by file name only.
referenced="$(grep -rhoE 'screenshots/[A-Za-z0-9_./-]+\.png' README.md docs/*.md docs/index.html 2>/dev/null \
  | sed 's#.*screenshots/##' | sort -u)"
captured="$(ls docs/screenshots 2>/dev/null | sort)"
missing="$(comm -23 <(printf '%s\n' "$referenced") <(printf '%s\n' "$captured"))"
unused="$(comm -13 <(printf '%s\n' "$referenced") <(printf '%s\n' "$captured"))"
if [ -n "$missing" ]; then
  fail "문서가 참조하지만 docs/screenshots에 없는 그림입니다 (PDF 생성이 실패합니다):"; printf '%s\n' "$missing"
fi
if [ -n "$unused" ]; then
  fail "찍어 두었지만 어느 문서도 싣지 않는 그림입니다 (문서를 고치거나 파일을 지우세요):"; printf '%s\n' "$unused"
fi
# The guides are shot at a 1440-wide desktop window (scripts/capture_all.js),
# and a picture pasted in by hand at some other size stands out on the page
# next to the rest. The width is the four big-endian bytes at offset 16 of a
# PNG (the IHDR chunk), which od can read without any image tooling. Only
# the width: a full-page capture is legitimately taller than 900.
narrow="$(for f in docs/screenshots/*.png; do
  [ -f "$f" ] || continue
  width="$(od -An -tu1 -j16 -N4 "$f" | awk '{print $1*16777216 + $2*65536 + $3*256 + $4}')"
  [ "$width" = "1440" ] || printf '%s (%s px)\n' "${f#docs/screenshots/}" "$width"
done)"
if [ -n "$narrow" ]; then
  fail "너비가 1440px 이 아닌 그림입니다 (scripts/capture_all.js 로 다시 찍으세요):"; printf '%s\n' "$narrow"
fi

step "가이드 PDF"
# The PDFs are committed next to the Markdown they are baked from, and
# nothing rebuilds them on its own: features.md was re-pointed at new
# captures while its PDF kept the old ones until someone opened it. md2pdf is
# not available everywhere, so this does not rebuild anything -- it only asks
# git whether a document (or a picture it embeds) changed after its PDF was
# last baked, in the working tree or in history. The mapping comes from the
# build script so the two cannot disagree.
while read -r name pdf sources; do
  # shellcheck disable=SC2086  # sources is a space-separated list of paths
  inputs="$sources $(grep -hoE 'screenshots/[A-Za-z0-9_./-]+\.png' $sources 2>/dev/null | sed 's#^#docs/#' | sort -u | tr '\n' ' ')"
  if [ ! -f "$pdf" ]; then
    fail "$name: $pdf 가 없습니다. scripts/build_docs_pdf.sh $name 으로 만드세요."
    continue
  fi
  # A PDF that is itself modified was just rebuilt; nothing to say.
  [ -n "$(git status --porcelain -- "$pdf")" ] && continue
  # shellcheck disable=SC2086
  if [ -n "$(git status --porcelain --untracked-files=all -- $inputs)" ]; then
    fail "$name: 원고를 고쳤지만 $pdf 는 그대로입니다. scripts/build_docs_pdf.sh $name 으로 다시 구우세요."
    continue
  fi
  # shellcheck disable=SC2086
  src_commit="$(git log -1 --format=%H -- $inputs)"
  pdf_commit="$(git log -1 --format=%H -- "$pdf")"
  if [ -n "$src_commit" ] && [ -n "$pdf_commit" ] && ! git merge-base --is-ancestor "$src_commit" "$pdf_commit"; then
    fail "$name: $pdf 를 마지막으로 구운 커밋($(git rev-parse --short "$pdf_commit")) 뒤에 원고가 바뀌었습니다($(git rev-parse --short "$src_commit")). scripts/build_docs_pdf.sh $name 으로 다시 구우세요."
  fi
done < <(bash scripts/build_docs_pdf.sh --list)

step "비밀정보 스캔"
# The scanner and its digest are read from the workflow: a second copy of the
# pin here would drift, and then this script would be checking something the
# pipeline no longer runs.
scanner="$(grep -o 'ghcr.io/gitleaks/gitleaks@sha256:[0-9a-f]\{64\}' .github/workflows/ci.yml | head -1)"
if [ -z "$scanner" ]; then
  fail "ci.yml에서 gitleaks image를 찾지 못했습니다. 워크플로가 바뀌었는지 확인하세요."
elif command -v docker >/dev/null 2>&1; then
  # --no-git, like the pipeline: what matters is the tree about to be pushed.
  # Scanning history here would report the same handful of old test literals
  # every time, which is how a check teaches people to ignore it.
  docker run --rm -v "$PWD:/repo" "$scanner" detect --source=/repo --no-git --redact --no-banner --exit-code 1 \
    || fail "비밀정보 스캔에서 걸린 항목이 있습니다. CI도 같은 이유로 멈춥니다."
else
  printf '건너뜀: docker가 없어 비밀정보 스캔을 돌릴 수 없습니다. CI에서는 반드시 돌아갑니다.\n'
fi

printf '\n'
if [ "$failed" -eq 0 ]; then
  printf '통과: 여기서 확인할 수 있는 것은 모두 통과했습니다.\n'
else
  printf '실패: 위 항목을 고친 뒤 다시 실행하세요.\n'
fi
exit "$failed"
// Package testdb gives tests a real PostgreSQL schema so that migrations,
// object-level authorization, workflow transitions and submission validation
// are exercised against the database they actually run on. Without
// TEST_POSTGRES_DSN the helpers skip, so `go test ./...` still works on a
// machine with no database.
package testdb

import (
	"context"
	"fmt"
	"os"
	"strings"
	"sync/atomic"
	"testing"
	"time"

	"github.com/hkjang/SecCheck/internal/store"
)

const DSNEnv = "TEST_POSTGRES_DSN"

var counter atomic.Int64

// DSN returns the configured test database, or "" when the suite should skip.
func DSN() string { return strings.TrimSpace(os.Getenv(DSNEnv)) }

// New creates an isolated schema, applies every migration to it and returns a
// Store bound to that schema. The schema is dropped when the test finishes, so
// parallel packages never see each other's rows.
func New(t *testing.T) *store.Store {
	t.Helper()
	return open(t, true)
}

func open(t *testing.T, migrate bool) *store.Store {
	t.Helper()
	dsn := DSN()
	if dsn == "" {
		t.Skipf("%s is not set; skipping the database-backed test", DSNEnv)
	}
	ctx, cancel := context.WithTimeout(context.Background(), 90*time.Second)
	defer cancel()

	admin, err := store.Open(ctx, dsn)
	if err != nil {
		t.Fatalf("connect %s: %v", DSNEnv, err)
	}
	schema := fmt.Sprintf("t%d_%d", time.Now().UnixNano()%1e9, counter.Add(1))
	if _, err = admin.Pool.Exec(ctx, `CREATE SCHEMA `+schema); err != nil {
		admin.Close()
		t.Fatalf("create schema %s: %v", schema, err)
	}

	scoped, err := store.Open(ctx, store.WithSearchPath(dsn, schema))
	if err != nil {
		_, _ = admin.Pool.Exec(ctx, `DROP SCHEMA `+schema+` CASCADE`)
		admin.Close()
		t.Fatalf("connect to schema %s: %v", schema, err)
	}
	if err = migrateIf(migrate, ctx, scoped); err != nil {
		scoped.Close()
		_, _ = admin.Pool.Exec(ctx, `DROP SCHEMA `+schema+` CASCADE`)
		admin.Close()
		t.Fatalf("migrate schema %s: %v", schema, err)
	}
	t.Cleanup(func() {
		scoped.Close()
		dropCtx, stop := context.WithTimeout(context.Background(), 30*time.Second)
		defer stop()
		if _, err := admin.Pool.Exec(dropCtx, `DROP SCHEMA `+schema+` CASCADE`); err != nil {
			t.Logf("drop schema %s: %v", schema, err)
		}
		admin.Close()
	})
	return scoped
}

// Bootstrap creates the initial administrator the way main does, and returns
// the user id.
func Bootstrap(t *testing.T, s *store.Store, username string) string {
	t.Helper()
	ctx := context.Background()
	if err := s.UpsertBootstrap(ctx, store.NewID(), username, "$2a$04$C4a8yXqTRIYQGvPMqmzZ2eOWiHZs4v4CjJZaFn8DR5JzS0/oCJhwq"); err != nil {
		t.Fatalf("bootstrap %s: %v", username, err)
	}
	u, err := s.GetUserByUsername(ctx, username)
	if err != nil {
		t.Fatalf("load %s: %v", username, err)
	}
	return u.ID
}

func migrateIf(migrate bool, ctx context.Context, s *store.Store) error {
	if !migrate {
		return nil
	}
	return s.Migrate(ctx)
}

// Bare creates an isolated empty schema and returns a Store bound to it with
// no migrations applied, for tests that need to build a database up from some
// earlier state themselves.
func Bare(t *testing.T) *store.Store {
	t.Helper()
	return open(t, false)
}
