	query := r.URL.Query()
	for _, key := range []string{"from", "to", "department"} {
		if value := strings.TrimSpace(stringValue(args[key])); value != "" {
			query.Set(key, value)
		}
	}
	scoped := r.Clone(r.Context())
	scoped.URL.RawQuery = query.Encode()
	return s.buildReport(scoped, reportFilter(scoped))
}

